import React, { useEffect, useState } from 'react';
import { getCar } from '../services/carService';
import { getImageUrl } from '../services/api';
import { motion } from 'framer-motion';
import styles from './ComparePage.module.css';

const ComparePage = () => {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [removedIds, setRemovedIds] = useState([]);
  const [expandedDesc, setExpandedDesc] = useState(null);

  useEffect(() => {
    const compareIds = JSON.parse(localStorage.getItem('compareList') || '[]');
    if (compareIds.length === 0) {
      setLoading(false);
      return;
    }

    const fetchCars = async () => {
      const loaded = [];
      const invalid = [];
      for (const id of compareIds) {
        try {
          const res = await getCar(id);
          loaded.push(res.data);
        } catch { invalid.push(id); }
      }
      if (invalid.length) {
        const newList = compareIds.filter(id => !invalid.includes(id));
        localStorage.setItem('compareList', JSON.stringify(newList));
        setRemovedIds(invalid);
      }
      setCars(loaded);
      setLoading(false);
    };
    fetchCars();
  }, []);

  const clearCompare = () => {
    localStorage.removeItem('compareList');
    window.location.reload();
  };

  const removeCar = (id) => {
    const newIds = JSON.parse(localStorage.getItem('compareList') || '[]').filter(i => i !== id);
    localStorage.setItem('compareList', JSON.stringify(newIds));
    setCars(prev => prev.filter(c => c.id !== id));
  };

  if (loading) return <div className={styles.loading}>Загрузка...</div>;
  if (cars.length === 0) return <div className={styles.empty}>Нет автомобилей для сравнения. Добавьте их из каталога.</div>;

  // Вспомогательные функции для форматирования
  const formatPrice = (price) => price ? `${price.toLocaleString()} ₽` : '—';
  const formatBool = (val) => (val === true ? 'Да' : val === false ? 'Нет' : '—');
  const formatBodyType = (type) => {
    const dict = { sedan: 'Седан', suv: 'Внедорожник', coupe: 'Купе', cabriolet: 'Кабриолет', wagon: 'Универсал', pickup: 'Пикап', limousine: 'Лимузин', hatchback: 'Хэтчбек' };
    return dict[type] || type || '—';
  };
  const formatFuel = (fuel) => {
    const dict = { petrol: 'Бензин', diesel: 'Дизель', hybrid: 'Гибрид', electric: 'Электро' };
    return dict[fuel] || fuel || '—';
  };
  const formatDrive = (drive) => {
    const dict = { FWD: 'Передний', RWD: 'Задний', AWD: 'Полный' };
    return dict[drive] || drive || '—';
  };
  const formatTransmission = (trans) => {
    const dict = { manual: 'Механика', automatic: 'Автомат', robot: 'Робот', variator: 'Вариатор' };
    return dict[trans] || trans || '—';
  };

  const formatValue = (car, key) => {
    const val = car[key];
    if (val === null || val === undefined || val === '') return '—';
    return String(val);
  };

  const isDifferent = (key) => {
    const vals = cars.map(car => formatValue(car, key));
    return new Set(vals).size > 1;
  };

  const renderField = (car, label, key, formatter) => {
    const raw = car[key];
    const value = formatter ? formatter(raw) : formatValue(car, key);
    const diff = isDifferent(key);
    return (
      <div key={key} className={`${styles.field} ${diff ? styles.diffField : ''}`}>
        <span className={styles.fieldLabel}>{label}</span>
        <span className={styles.fieldValue}>{value}</span>
      </div>
    );
  };

  return (
    <motion.div className={styles.page} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      {removedIds.length > 0 && (
        <div className={styles.warning}>Некоторые автомобили были удалены из каталога и исключены из сравнения.</div>
      )}
      <div className={styles.header}>
        <h1 className={styles.title}>Сравнение автомобилей</h1>
        <button className={styles.clearBtn} onClick={clearCompare}>Очистить всё</button>
      </div>

      <div className={styles.cardsContainer}>
        {cars.map(car => (
          <div key={car.id} className={styles.carCard}>
            <div className={styles.cardHeader}>
              <button className={styles.removeCarBtn} onClick={() => removeCar(car.id)}>✕</button>
            </div>
            <img src={getImageUrl(car.image_url)} alt={car.model} className={styles.carImage} />
            <h3 className={styles.carName}>{car.brand} {car.model}</h3>

            {/* Основные */}
            <div className={styles.group}>
              <h4 className={styles.groupTitle}>Основные</h4>
              {renderField(car, 'Год', 'year')}
              {renderField(car, 'Цена', 'price', formatPrice)}
              {renderField(car, 'Кузов', 'body_type', formatBodyType)}
              {renderField(car, 'Рестайлинг', 'restyling', formatBool)}
            </div>

            {/* Двигатель и топливо */}
            <div className={styles.group}>
              <h4 className={styles.groupTitle}>Двигатель и топливо</h4>
              {renderField(car, 'Объём двигателя, л', 'engine_volume')}
              {renderField(car, 'Мощность, л.с.', 'power')}
              {renderField(car, 'Топливо', 'fuel_type', formatFuel)}
              {renderField(car, 'Расход, л/100км', 'consumption')}
            </div>

            {/* Трансмиссия и динамика */}
            <div className={styles.group}>
              <h4 className={styles.groupTitle}>Трансмиссия и динамика</h4>
              {renderField(car, 'Привод', 'drive_type', formatDrive)}
              {renderField(car, 'КПП', 'transmission', formatTransmission)}
              {renderField(car, '0-100 км/ч, с', 'acceleration')}
              {renderField(car, 'Макс. скорость, км/ч', 'max_speed')}
            </div>

            {/* Размеры */}
            <div className={styles.group}>
              <h4 className={styles.groupTitle}>Размеры</h4>
              {renderField(car, 'Клиренс, мм', 'clearance')}
              {renderField(car, 'Мест', 'seats')}
            </div>

            {/* Описание */}
            <div className={styles.group}>
              <h4 className={styles.groupTitle}>Описание</h4>
              <div className={styles.descriptionBox}>
                <span className={`${styles.descText} ${expandedDesc === car.id ? styles.expanded : ''}`}>
                  {car.description || '—'}
                </span>
                {car.description && car.description.length > 80 && (
                  <button
                    className={styles.moreBtn}
                    onClick={() => setExpandedDesc(expandedDesc === car.id ? null : car.id)}
                  >
                    {expandedDesc === car.id ? 'Свернуть' : 'Ещё'}
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </motion.div>
  );
};

export default ComparePage;
